{
  "summary": "Based on the available Rho-Bank terms, the Business Gold Rewards Card is the strongest documented business-card option for a $100,000 purchase, provided you qualify and receive a sufficient credit limit.",
  "options": [
    {
      "card": "Business Gold Rewards Card",
      "eligibility": {
        "minimum_personal_credit_score": 735,
        "minimum_business_PAYDEX_score": 67
      },
      "credit_limit": "$37,500–$225,000, subject to approval",
      "annual_fee": "$200",
      "rewards": {
        "operations_spending": "2.5% cash back",
        "all_other_purchases": "1.0% cash back"
      },
      "estimated_reward_on_100000": {
        "if_coded_as_operations_spending": "$2,500 cash back",
        "if_coded_as_an_other_purchase": "$1,000 cash back"
      },
      "estimated_first_year_net_after_annual_fee": {
        "if_coded_as_operations_spending": "$2,300",
        "if_coded_as_an_other_purchase": "$800"
      },
      "important_note": "The available terms do not specify how an Apple Music subscription will be categorized. Do not assume it will receive the 2.5% operations rate."
    },
    {
      "card": "Business Silver Rewards Card",
      "eligibility": {
        "minimum_personal_credit_score": 700,
        "established_business_PAYDEX_score": 47
      },
      "credit_limit": "$17,500–$112,500, subject to approval",
      "annual_fee": "$122.50, waived for the first year for new customers",
      "rewards": "The available terms do not state the rewards rate, so I cannot calculate its return accurately.",
      "fit_for_purchase": "A $100,000 charge could fit within the published maximum limit, but approval and the assigned limit are not guaranteed."
    },
    {
      "card": "Green Rewards Card",
      "eligibility": {
        "minimum_personal_FICO_score": 690,
        "established_business_PAYDEX_score": 42; "newer businesses may be evaluated using personal credit"
      },
      "credit_limit": "$14,000–$75,000",
      "annual_fee": "$100",
      "rewards": "The available terms do not state the rewards rate.",
      "fit_for_purchase": "Its published maximum limit is below the planned $100,000 purchase, so it is not a practical single-card solution unless the transaction can be split and the merchant permits that."
    },
    {
      "card": "Business Bronze Rewards Card",
      "eligibility": {
        "minimum_personal_FICO_score": 660
      },
      "credit_limit": "Starting credit line of at least $10,000; final limit is subject to approval",
      "annual_fee": "$0",
      "rewards": "1.0% cash back",
      "new_customer_bonus": "$500 statement credit after $10,000 in eligible purchases within the first 2 months",
      "estimated_reward_on_100000": "$1,000 cash back, plus the $500 bonus if the promotion is available and requirements are met",
      "fit_for_purchase": "The published starting line is far below the purchase amount, so do not rely on this card for a $100,000 single transaction without receiving a confirmed sufficient limit."
    }
  ],
  "recommendation": "First consider the Business Gold Rewards Card because it is the only documented business option with a credit limit potentially large enough for the entire charge. Its best-case return is $2,500 cash back, or approximately $2,300 after the annual fee. However, if Apple Music is treated as an ordinary non-operations purchase, the return would be approximately $800 net after the annual fee. Confirm the merchant category and request a credit limit sufficient for the full charge before making the purchase.",
  "payment_warning": "Paying the balance in full is important. The Business Gold APR is 17.99% on carried balances, which could substantially outweigh the rewards if the $100,000 balance is not promptly paid.",
  "limitations": "I cannot guarantee approval, the assigned credit limit, merchant coding, or promotional availability. The available information does not provide enough detail to calculate the Business Silver or Green card rewards accurately."
}
